webpackJsonp([0x9affe2d730fb],{466:function(e,t){e.exports={data:{site:{siteMetadata:{title:"Mihail Eric",subtitle:"Engineer, researcher, educator.",copyright:"Copyright",menu:[{label:"Blog",path:"/blog/"},{label:"Projects",path:"/projects/"},{label:"Teaching",path:"/teaching/"}],author:{name:"Mihail Eric",email:"mihail911@gmail.com",twitter:"mihail_eric",github:"mihail911",linkedin:"mihaileric"}}},markdownRemark:{id:"/Users/mihaileric/Documents/Projects/mihail911.github.io/src/pages/pages/2018-09-12---teaching/index.md absPath of file >>> MarkdownRemark",html:'<p>I believe that teaching is the best way to learn. </p>\n<p>I am the creator of the Artificial Intelligence School, a mobile app for learning the basics of artificial intelligence, machine learning, and deep learning.\nCheck it out on the <a href="https://itunes.apple.com/us/app/artificial-intelligence-school/id1369987569?mt=8b">App Store</a> and <a href="https://play.google.com/store/apps/details?id=com.theaischool">Google Play</a>.</p>\n<p>In the past, I have been a teaching assistant at Stanford for the following courses:</p>\n<ul>\n<li><a href="http://web.stanford.edu/class/cs106a/">CS106A (Programming Methodology)</a></li>\n<li><a href="http://web.stanford.edu/class/cs106b/">CS106B (Programming Abstractions)</a></li>\n<li><a href="http://web.stanford.edu/class/cs224n/">CS224N (Natural Language Processing)</a></li>\n<li><a href="http://web.stanford.edu/class/cs109/">CS109 (Introduction to Probability for Computer Scientists)</a></li>\n</ul>\n<p>Before that I was also actively involved with the <a href="https://artofproblemsolving.com/">Art of Problem Solving</a> community, where I was a teaching assistant for the following courses:</p>\n<ul>\n<li>Mathcounts Problem Series</li>\n<li>Introduction to Algebra</li>\n<li>Introduction to Programming</li>\n</ul>',frontmatter:{title:"Teaching",date:null,description:null}}},pathContext:{slug:"/teaching"}}}});
